function syncListening(s=playing?.s,a=playing?.a){const root=document.querySelector('.listening-page');if(!root)return;if(!s||!a){s=+document.getElementById('listen-surah-choice').value;a=+document.getElementById('listen-ayah-choice').value||1}if(!validRef(s,a))return;root.classList.toggle('is-playing',!!playing&&!audio.paused&&!audio.ended);document.getElementById('listen-status').textContent=playing?(audio.ended?'Tamamlandı':audio.paused?'Duraklatıldı':'Dinleniyor'):'Hazır';document.getElementById('listen-current-label').textContent=playing?'Şimdi dinlenen ayet':'Dinlemeye eşlik et';document.getElementById('listening-title').textContent=names[s-1]+' Suresi';document.getElementById('listening-ar').textContent=surahs[s-1].ayahs[a-1].text;document.getElementById('listening-tr').textContent=translations[s-1].ayahs[a-1].text;document.getElementById('listening-ref').textContent=`${a}. ayet / ${surahs[s-1].ayahs.length} · Diyanet Meali`;document.getElementById('listen-open-text').onclick=()=>openSurah(s,a);document.getElementById('reciter-avatar').textContent=chosenReciter().initials;document.getElementById('reciter-name').textContent=chosenReciter().name;document.getElementById('listen-reciter').value=audioPrefs.reciter;updateSleepLabels();}
