function sleepDescription(){if(sleepMode==='off')return 'Zamanlayıcı kapalı.';if(sleepMode==='surah')return 'Geçerli sure tamamlanınca dinleme durur.';const seconds=Math.max(0,Math.ceil((sleepDeadline-Date.now())/1000));return 'Dinleme '+formatTime(seconds)+' sonra duraklatılacak.'}
function updateSleepLabels(){const status=document.getElementById('sleep-status');if(status)status.textContent=sleepDescription();const button=document.getElementById('listen-sleep-text');if(button)button.textContent=sleepMode==='off'?'Uyku zamanlayıcısı':sleepMode==='surah'?'Sure bitince dur':formatTime(Math.max(0,(sleepDeadline-Date.now())/1000))+' sonra dur';const badge=document.getElementById('audio-timer-badge');if(badge){badge.textContent=sleepMode==='off'?'':sleepMode==='surah'?'Sure sonu':formatTime(Math.max(0,(sleepDeadline-Date.now())/1000));badge.hidden=sleepMode==='off'}}
