function setSleepTimer(mode){clearSleepTimer();if(mode==='off'){toast('Uyku zamanlayıcısı kapatıldı.');return}sleepMode=mode;if(mode==='surah'){repeatVerse=false;updatePlayer()}else if(['10','20','30','60'].includes(mode)){sleepDeadline=Date.now()+Number(mode)*60000;sleepTimeout=setTimeout(checkSleepDeadline,Number(mode)*60000);sleepTicker=setInterval(()=>{checkSleepDeadline();updateSleepLabels()},1000)}else{clearSleepTimer();return}updateSleepLabels();toast(mode==='surah'?'Dinleme sure sonunda duracak.':mode+' dakikalık zamanlayıcı başladı.')}
function checkSleepDeadline(){if(sleepDeadline&&Date.now()>=sleepDeadline){stopStudio(false,'Zamanlayıcı tamamlandı; çalışma durdu.');audio.pause();clearSleepTimer();toast('Uyku zamanlayıcısı tamamlandı. Dinleme duraklatıldı.');return true}return false}
