function navItem(id,label,ico,extra=''){return `<button class="nav-item ${page===id?'active':''}" data-nav="${id}">${icon(ico)}<span>${label}</span>${extra}</button>`}
function shell(){document.getElementById('app').innerHTML=`<aside class="sidebar"><a class="brand" href="#" aria-label="Nûr ana sayfa"><span class="brand-mark">۞</span><div><strong>nûr</strong><small>KUR’AN-I KERİM</small></div></a><div class="nav-label">YOLCULUĞUN</div><nav>${navItem('home','Ana Sayfa','home')}${navItem('quran','Kur’an-ı Kerim','book')}${navItem('explore','Keşfet','compass')}${navItem('plan','Okuma Planım','clock')}${navItem('studio','Ezber Stüdyosu','spark')}${navItem('saved','Kaydettiklerim','bookmark')}${navItem('listen','Dinle','headphones')}</nav><div class="side-bottom">${navItem('settings','Görünüm ve Ayarlar','settings')}${navItem('about','Nûr Hakkında','heart')}<div class="side-verse"><p lang="ar" dir="rtl">نُورٌ عَلَىٰ نُورٍ</p><small>Nûr üstüne nûr.<br>Nûr Suresi, 35. ayetten</small></div><footer>Bir ayet. Bin anlam. Sonsuz yolculuk.</footer></div></aside><div class="main"><header class="topbar"><div class="breadcrumb">${icon('home')}<span>/</span><strong id="crumb">Ana Sayfa</strong></div><div class="searchbox">${icon('search')}<input id="search" aria-label="Sure veya mealde ara" placeholder="Sure, ayet veya bir kelime ara..."><kbd>⌘ K</kbd></div><div class="top-actions"><button class="icon-button" data-action="theme" title="Görünümü değiştir">${icon('moon')}</button><button class="avatar" data-action="profile" title="Okuma yolculuğun">N</button></div></header><main id="content" class="content"></main></div><div id="player" class="audio-player hidden"></div>`;bindShell()}
