function mountMeaningScene(oldHero){const scene=document.createElement('section');scene.className='meaning-scene discovery-hero';scene.setAttribute('aria-label','Anlam evreni: kavram seçerek ayet keşfet');scene.innerHTML=`<div class="cosmos-atmosphere" aria-hidden="true"></div><div class="cosmos-stars" aria-hidden="true">${Array.from({length:45},(_,i)=>`<i style="--x:${(i*43+17)%100}%;--y:${(i*29+11)%100}%;--delay:${i%7}s;--s:${i%3===0?2:1}px"></i>`).join('')}</div><header class="cosmos-header"><div><span class="cosmos-eyebrow"><i></i> NÛR / ANLAM EVRENİ</span><h1>Bir kelimeye dokun.<br><em>Bir pencere açılsın.</em></h1><p>Bir listeyi değil, merakını takip et.</p></div><button id="cosmos-motion" aria-pressed="${cosmosState.paused}">${icon('pause')}<span>Hareketi durdur</span></button></header><div class="cosmos-experience"><div class="cosmos-map"><div class="cosmos-orbit" aria-hidden="true"><i></i><i></i><i></i></div><svg class="cosmos-lines" viewBox="0 0 600 500" preserveAspectRatio="none" aria-hidden="true">${[[300,65],[505,155],[505,350],[300,445],[95,350],[95,155]].map(([x,y],i)=>`<path data-cosmos-line="${i}" d="M300 250 Q${(x+300)/2+30} ${(y+250)/2-30} ${x} ${y}"/>`).join('')}</svg><div class="cosmos-center" aria-hidden="true"><span>ŞİMDİ KEŞFETTİĞİN</span><strong id="cosmos-center-word"></strong><i>bir başlangıç noktası</i></div>${[[50,13],[84.2,31],[84.2,70],[50,89],[15.8,70],[15.8,31]].map(([x,y],i)=>`<button class="cosmos-portal" data-cosmos-topic="${i}" style="--x:${x}%;--y:${y}%" aria-pressed="false"><span class="cosmos-portal-glyph">${icon(topics[i].ico)}</span><strong>${cosmosWords[i]}</strong><small>${topics[i].refs.length} durak</small></button>`).join('')}<span class="cosmos-coordinate" aria-hidden="true">06 KAVRAM / 19 DURAK</span><button id="cosmos-jump">Ayeti gör ↓</button></div><article class="cosmos-lens" id="cosmos-lens" aria-label="Seçili kavramın ayet penceresi"></article></div><footer class="cosmos-footer"><div><span>KEŞİF İZİN</span><nav id="cosmos-trail" aria-label="Bu oturumdaki kavram geçişlerin"></nav></div><p>Kavramlar ve aralarındaki geçişler editoryal seçimlerdir; tefsir veya metinsel bağlantı iddiası değildir. Görsel yerleşim dekoratiftir.</p></footer><span id="cosmos-status" class="sr-only" role="status"></span>`;oldHero.replaceWith(scene);addWorkbenchEntry(scene);addNumberBookEntry(scene);document.getElementById('cosmos-jump').onclick=()=>{const lens=document.getElementById('cosmos-lens');lens.setAttribute('tabindex','-1');lens.focus({preventScroll:true});lens.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth',block:'start'})};scene.querySelectorAll('[data-cosmos-topic]').forEach(b=>{b.onclick=()=>selectCosmos(+b.dataset.cosmosTopic);b.onkeydown=e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const n=e.key==='Home'?0:e.key==='End'?5:(+b.dataset.cosmosTopic+(e.key==='ArrowRight'?1:5))%6;selectCosmos(n);scene.querySelector(`[data-cosmos-topic="${n}"]`).focus({preventScroll:true})}}});document.getElementById('cosmos-motion').onclick=()=>{cosmosState.paused=!cosmosState.paused;store('nur-cosmos-paused',cosmosState.paused);syncCosmosMotion()};scene.onpointermove=e=>{if(cosmosState.paused||matchMedia('(prefers-reduced-motion:reduce)').matches||e.pointerType!=='mouse')return;const r=scene.getBoundingClientRect();scene.style.setProperty('--mx',((e.clientX-r.left)/r.width-.5)*12+'px');scene.style.setProperty('--my',((e.clientY-r.top)/r.height-.5)*12+'px')};scene.onpointerleave=()=>{scene.style.setProperty('--mx','0px');scene.style.setProperty('--my','0px')};syncCosmosMotion();renderCosmos();}
function syncCosmosMotion(){const scene=document.querySelector('.meaning-scene');if(!scene)return;const reduced=matchMedia('(prefers-reduced-motion:reduce)').matches;scene.classList.toggle('cosmos-paused',cosmosState.paused||reduced);const b=document.getElementById('cosmos-motion');b.disabled=reduced;b.setAttribute('aria-pressed',cosmosState.paused||reduced);b.querySelector('span').textContent=reduced?'Hareket azaltıldı':cosmosState.paused?'Hareketi aç':'Hareketi durdur';if(cosmosState.paused||reduced){scene.style.setProperty('--mx','0px');scene.style.setProperty('--my','0px')}}
function selectCosmos(topic){if(!Number.isInteger(topic)||topic<0||topic>5)return;if(topic!==cosmosState.topic){cosmosState.trail=[...cosmosState.trail,topic].slice(-5);cosmosState.topic=topic;cosmosState.step=0}renderCosmos();}
function renderCosmos(){const root=document.querySelector('.meaning-scene');if(!root)return;const {topic,step}=cosmosState,t=topics[topic],d=discoveryPaths[topic],[s,a]=t.refs[step];document.getElementById('cosmos-center-word').textContent=cosmosWords[topic];root.querySelectorAll('[data-cosmos-topic]').forEach(b=>b.setAttribute('aria-pressed',+b.dataset.cosmosTopic===topic));root.querySelectorAll('[data-cosmos-line]').forEach(p=>p.classList.toggle('is-active',+p.dataset.cosmosLine===topic));const lens=document.getElementById('cosmos-lens');lens.innerHTML=`<div class="cosmos-lens-top"><span>${cosmosWords[topic]} / ${step+1} — ${t.refs.length}</span><span class="cosmos-live-dot" aria-hidden="true"></span></div><h2>${d.question}</h2><div class="cosmos-quote-window"><blockquote>${safe(translations[s-1].ayahs[a-1].text)}</blockquote></div><div class="cosmos-source"><span>${names[s-1]} · ${a}. ayet<small>Diyanet Meali · ${s}:${a}</small></span><div><button id="cosmos-prev" aria-label="Seçkide önceki ayet">${icon('back')}</button><button id="cosmos-next" aria-label="Seçkide sonraki ayet">${icon('arrow')}</button></div></div><button id="cosmos-open">Bu ayetin izini sür ${icon('arrow')}</button><div class="cosmos-secondary"><button id="cosmos-context">Sure içinde oku</button><button id="cosmos-listen">${icon('headphones')} Buradan dinle</button></div><div class="cosmos-bridges"><span>BAŞKA BİR YÖNE BAK · EDİTORYAL</span><div>${cosmosBridges[topic].map(n=>`<button data-cosmos-bridge="${n}">${cosmosWords[n]} ${icon('arrow')}</button>`).join('')}</div></div>`;document.getElementById('cosmos-prev').onclick=()=>{cosmosState.step=(step+t.refs.length-1)%t.refs.length;renderCosmos();document.getElementById('cosmos-prev').focus({preventScroll:true})};document.getElementById('cosmos-next').onclick=()=>{cosmosState.step=(step+1)%t.refs.length;renderCosmos();document.getElementById('cosmos-next').focus({preventScroll:true})};document.getElementById('cosmos-open').onclick=()=>openDiscovery(topic,step);document.getElementById('cosmos-context').onclick=()=>openSurah(s,a);document.getElementById('cosmos-listen').onclick=()=>playVerse(s,a,{force:true});root.querySelectorAll('[data-cosmos-bridge]').forEach(b=>b.onclick=()=>{selectCosmos(+b.dataset.cosmosBridge);root.querySelector(`[data-cosmos-topic="${cosmosState.topic}"]`).focus({preventScroll:true})});const trail=document.getElementById('cosmos-trail');trail.innerHTML=cosmosState.trail.map((n,i)=>`${i?'<span aria-hidden="true">/</span>':''}<button data-cosmos-trail="${n}" ${i===cosmosState.trail.length-1?'aria-current="true"':''}>${cosmosWords[n]}</button>`).join('');trail.querySelectorAll('button').forEach(b=>b.onclick=()=>{selectCosmos(+b.dataset.cosmosTrail);root.querySelector(`[data-cosmos-topic="${cosmosState.topic}"]`).focus({preventScroll:true})});document.getElementById('cosmos-status').textContent=`${cosmosWords[topic]}. ${names[s-1]}, ${a}. ayet. Seçkide ${step+1} / ${t.refs.length}.`;}

let verseCollections=[],compareRefs=[],wbMode='masa',wbCollection=null,cardRef={s:94,a:5},cardPrefs={theme:'sage',format:'square',language:'both'},cardGeneration=0;
const canonicalKey=k=>k.split(':').map(Number).join(':');
function validCollections(rows){return Array.isArray(rows)&&rows.length<=50&&new Set(rows.map(c=>c?.id)).size===rows.length&&rows.every(c=>c&&typeof c.id==='string'&&/^c-[a-z0-9-]{6,70}$/.test(c.id)&&typeof c.name==='string'&&c.name.trim().length>0&&c.name.length<=60&&Array.isArray(c.refs)&&c.refs.length<=200&&c.refs.every(validKey))}
function mergeVerseCollections(incoming){const merged=verseCollections.map(c=>({...c,refs:[...c.refs]}));for(const c of incoming){const existing=merged.find(x=>x.id===c.id);if(existing)existing.refs=[...new Set([...existing.refs,...c.refs.map(canonicalKey)])];else merged.push({id:c.id,name:c.name,refs:[...new Set(c.refs.map(canonicalKey))]})}if(!validCollections(merged))throw Error('collection limits');return merged}
function persistCollections(){store('nur-collections',verseCollections)}
function initWorkbench(){const c=read('nur-collections',[]);verseCollections=validCollections(c)?c.map(x=>({id:x.id,name:x.name,refs:[...new Set(x.refs.map(canonicalKey))]})):[];const refs=read('nur-compare',[]);compareRefs=Array.isArray(refs)?[...new Set(refs.filter(validKey).map(canonicalKey))].slice(0,3):[];const nav=document.querySelector('.sidebar nav');const b=document.createElement('button');b.className='nav-item';b.dataset.nav='workbench';b.innerHTML=icon('edit')+' Ayet Atölyesi';b.onclick=()=>openWorkbench('masa');nav.append(b)}
function addWorkbenchEntry(after){const row=document.createElement('section');row.className='wb-launch';row.setAttribute('aria-label','Üç ayet aracı');row.innerHTML=[['masa','copy','Karşılaştırma masası','Üç ayeti birlikte düşün.'],['koleksiyonlar','bookmark','Kişisel koleksiyonlar','Kendi ayet seçkini oluştur.'],['kart','spark','Ayet kartı stüdyosu','Anlamı bir görsele taşı.']].map(([mode,ico,title,sub],i)=>`<button data-wb-launch="${mode}"><span>${icon(ico)}<small>0${i+1}</small></span><strong>${title}</strong><p>${sub}</p>${icon('arrow')}</button>`).join('');after.after(row);row.querySelectorAll('button').forEach(b=>b.onclick=()=>openWorkbench(b.dataset.wbLaunch))}
function addWorkbenchVerseTool(v,key){const b=document.createElement('button');b.className='study-button wb-verse-tools';b.innerHTML=icon('spark')+' Masa · Koleksiyon · Kart';b.onclick=()=>showVerseWorkbench(key);v.append(b)}
function showVerseWorkbench(key){if(!validKey(key))return;const [s,a]=key.split(':').map(Number);openModal(names[s-1]+' · '+a+'. ayet',`<p>Bu ayetle ne yapmak istersin?</p><div class="wb-actions"><button id="wb-add-compare">${icon('copy')} Karşılaştırma masasına ekle ${icon('arrow')}</button><button id="wb-add-collection">${icon('bookmark')} Koleksiyona ekle ${icon('arrow')}</button><button id="wb-make-card">${icon('spark')} Ayet kartı hazırla ${icon('arrow')}</button></div>`);document.getElementById('wb-add-compare').onclick=()=>{if(addCompare(key))openWorkbench('masa')};document.getElementById('wb-add-collection').onclick=()=>showCollectionPicker(key);document.getElementById('wb-make-card').onclick=()=>openWorkbench('kart',{s,a})}
function addCompare(key){key=canonicalKey(key);if(compareRefs.includes(key))return true;if(compareRefs.length>=3){toast('Masada en fazla üç ayet olabilir. Önce bir ayeti kaldır.');return false}compareRefs.push(key);store('nur-compare',compareRefs);return true}
function newCollection(name,key){name=name.trim();if(!name){toast('Koleksiyonuna bir ad ver.');return null}if(name.length>60||verseCollections.length>=50){toast('En fazla 50 koleksiyon ve 60 karakterlik ad kullanılabilir.');return null}const c={id:'c-'+crypto.randomUUID(),name,refs:key?[canonicalKey(key)]:[]};verseCollections.push(c);persistCollections();return c}
function collectionAdd(id,key){const c=verseCollections.find(x=>x.id===id);if(!c||!validKey(key))return false;key=canonicalKey(key);if(c.refs.includes(key)){toast('Bu ayet zaten koleksiyonda.');return true}if(c.refs.length>=200){toast('Bir koleksiyona en fazla 200 ayet eklenebilir.');return false}c.refs.push(key);persistCollections();toast('Koleksiyonuna eklendi.');return true}
function showCollectionPicker(key){openModal('Koleksiyonuna ekle',`<p>Ayet yalnızca seçkine eklenir; mevcut kayıtların ve notların değişmez.</p><div class="wb-collection-choices">${verseCollections.map(c=>`<button data-collection-pick="${c.id}"><strong>${safe(c.name)}</strong><span>${c.refs.length} ayet ${c.refs.includes(key)?'· Ekli':''}</span>${icon('arrow')}</button>`).join('')||'<p>İlk koleksiyonunu aşağıdan oluştur.</p>'}</div><form id="wb-new-collection"><label for="wb-collection-name">Yeni koleksiyon adı</label><input id="wb-collection-name" maxlength="60" required placeholder="Örn. Tekrar okuyacaklarım"><button class="solid-button" type="submit">Oluştur ve bu ayeti ekle</button></form>`);document.querySelectorAll('[data-collection-pick]').forEach(b=>b.onclick=()=>{if(collectionAdd(b.dataset.collectionPick,key))closeModal()});document.getElementById('wb-new-collection').onsubmit=e=>{e.preventDefault();if(newCollection(document.getElementById('wb-collection-name').value,key)){closeModal();toast('Koleksiyon oluşturuldu; ayet eklendi.')}}}
function wbPicker(id,ref={s:1,a:1},label='Ekle'){return `<form class="wb-picker" id="${id}"><label>Sure<select name="surah" aria-label="Sure">${surahs.map(s=>`<option value="${s.number}" ${s.number===ref.s?'selected':''}>${s.number}. ${names[s.number-1]}</option>`).join('')}</select></label><label>Ayet<input name="ayah" type="number" min="1" max="${surahs[ref.s-1].ayahs.length}" value="${ref.a}" required aria-label="Ayet numarası"></label><button class="solid-button" type="submit">${label} ${icon('arrow')}</button></form>`}
function bindWbPicker(id,callback){const form=document.getElementById(id);if(!form)return;form.elements.surah.onchange=()=>{form.elements.ayah.max=surahs[+form.elements.surah.value-1].ayahs.length;form.elements.ayah.value=1};form.onsubmit=e=>{e.preventDefault();const s=+form.elements.surah.value,a=+form.elements.ayah.value;if(validRef(s,a))callback(s,a)}}
function openWorkbench(mode='masa',ref=null){if(!['masa','koleksiyonlar','kart'].includes(mode))mode='masa';if(ref&&validRef(ref.s,ref.a))cardRef=ref;wbMode=mode;page='workbench';closeModal();observer?.disconnect();focusMode=false;document.body.classList.remove('focus-mode');document.querySelectorAll('[data-nav]').forEach(b=>b.classList.toggle('active',b.dataset.nav==='workbench'||(b.dataset.nav==='saved'&&!!b.closest('.mobile-navigation'))));document.getElementById('crumb').textContent='Ayet Atölyesi';if(!routeSync)history.pushState(null,'',mode==='kart'?`#atolye/kart/${cardRef.s}/${cardRef.a}`:'#atolye/'+mode);document.getElementById('content').innerHTML=`<div class="workbench-page fade-in"><header class="wb-header"><span class="mini-label">OKU · BİR ARAYA GETİR · PAYLAŞ</span><h1>Ayetlerle kendi alanını kur.</h1><p>Bir karşılaştırma, kişisel bir seçki veya sana ait bir kart.</p></header><nav class="wb-tabs" aria-label="Ayet Atölyesi araçları">${[['masa','copy','Karşılaştırma'],['koleksiyonlar','bookmark','Koleksiyonlar'],['kart','spark','Kart Stüdyosu']].map(([m,ico,title])=>`<button data-wb-tab="${m}" aria-current="${mode===m?'page':'false'}">${icon(ico)} ${title}</button>`).join('')}</nav><section id="wb-body"></section></div>`;document.querySelectorAll('[data-wb-tab]').forEach(b=>b.onclick=()=>openWorkbench(b.dataset.wbTab));if(mode==='masa')renderCompare();else if(mode==='koleksiyonlar')renderCollections();else renderCardStudio();window.scrollTo(0,0)}
function commonCompareWords(){const counts=new Map(),stop=new Set(['olan','olarak','onlar','onları','onlara','için','ile','daha','diye','gibi','bunu','buna','bütün','ancak']);for(const key of compareRefs){const[s,a]=key.split(':').map(Number),words=new Set((translations[s-1].ayahs[a-1].text.match(/\p{L}+/gu)||[]).map(foldSearch).filter(w=>w.length>=4&&!stop.has(w)));for(const w of words)counts.set(w,(counts.get(w)||0)+1)}return new Set([...counts].filter(([,n])=>n>1).map(([w])=>w))}
function compareText(text,common,on){return text.split(/(\p{L}+)/gu).map(word=>on&&common.has(foldSearch(word))?`<mark>${safe(word)}</mark>`:safe(word)).join('')}
function renderCompare(highlight=false){const common=commonCompareWords();document.getElementById('wb-body').innerHTML=`<div class="wb-section-heading"><div><h2>Yan yana, kendi bakışınla.</h2><p>En fazla üç ayet seç. Benzerlikleri ve farkları kendin incele; bu araç tefsir üretmez.</p></div><span>${compareRefs.length} / 3 AYET</span></div>${wbPicker('wb-compare-picker',{s:94,a:5},'Masaya ekle')}<label class="wb-highlight"><input id="wb-common" type="checkbox" ${highlight?'checked':''}> Ortak kelimeleri vurgula (yazım normalleştirilir)</label><p class="wb-fine">Büyük/küçük harf ve aksan farkları yok sayılır; kelime kökü veya anlam analizi yapılmaz. Görünüm, okuma ekranının tek-dil tercihinden bağımsızdır.</p><div class="wb-compare-grid" style="--compare-columns:${Math.max(1,compareRefs.length)}">${compareRefs.map((key,i)=>{const[s,a]=key.split(':').map(Number);return `<article class="wb-compare-card"><header><span>0${i+1}</span><button data-compare-remove="${key}" aria-label="${safe(names[s-1]+' '+a+'. ayeti masadan kaldır')}">${icon('close')}</button></header><h3>${names[s-1]} · ${a}. ayet</h3><details><summary>Arapça metin</summary><p class="wb-ar" lang="ar" dir="rtl">${safe(surahs[s-1].ayahs[a-1].text)}</p></details><p class="wb-meal">${compareText(translations[s-1].ayahs[a-1].text,common,highlight)}</p><small>Diyanet Meali · ${key}</small><footer><button data-wb-context="${key}">Sure içinde oku ${icon('arrow')}</button><button data-wb-tools="${key}">${icon('spark')} Araçlar</button></footer></article>`}).join('')||`<div class="wb-empty">${icon('copy')}<h3>İlk iki ayetini masaya koy.</h3><p>Ayet numarasını seçerek başlayabilir ya da İnşirâh 5–6 ile deneyebilirsin.</p><button id="wb-compare-demo" class="solid-button">İnşirâh 5–6 ile dene</button></div>`}</div>`;bindWbPicker('wb-compare-picker',(s,a)=>{if(addCompare(s+':'+a))renderCompare(highlight)});document.getElementById('wb-common').onchange=e=>{renderCompare(e.target.checked);document.getElementById('wb-common').focus({preventScroll:true})};document.querySelectorAll('[data-compare-remove]').forEach(b=>b.onclick=()=>{compareRefs=compareRefs.filter(k=>k!==b.dataset.compareRemove);store('nur-compare',compareRefs);renderCompare(highlight)});document.getElementById('wb-compare-demo')?.addEventListener('click',()=>{compareRefs=['94:5','94:6'];store('nur-compare',compareRefs);renderCompare()});bindWorkbenchLinks()}
function bindWorkbenchLinks(){document.querySelectorAll('[data-wb-context]').forEach(b=>b.onclick=()=>openSurah(...b.dataset.wbContext.split(':').map(Number)));document.querySelectorAll('[data-wb-tools]').forEach(b=>b.onclick=()=>showVerseWorkbench(b.dataset.wbTools))}
function renderCollections(){if(!verseCollections.some(c=>c.id===wbCollection))wbCollection=verseCollections[0]?.id||null;const c=verseCollections.find(x=>x.id===wbCollection);document.getElementById('wb-body').innerHTML=`<div class="wb-section-heading"><div><h2>Senin seçkin. Senin düzenin.</h2><p>Koleksiyonlar yalnızca cihazında saklanır ve kişisel veri yedeğine dahildir.</p></div></div><form id="wb-create-folder" class="wb-create-folder"><label class="sr-only" for="wb-folder-name">Yeni koleksiyon adı</label><input id="wb-folder-name" maxlength="60" required placeholder="Yeni koleksiyon adı…"><button class="solid-button">${icon('bookmark')} Oluştur</button></form><div class="wb-collections-layout"><nav class="wb-folder-list" aria-label="Koleksiyonların">${verseCollections.map(x=>`<button data-folder="${x.id}" aria-current="${x.id===wbCollection?'true':'false'}">${icon('bookmark')}<span>${safe(x.name)}<small>${x.refs.length} ayet</small></span></button>`).join('')||'<p>Henüz koleksiyonun yok.</p>'}</nav><section class="wb-folder-content">${c?`<header><div><span class="mini-label">KİŞİSEL SEÇKİN</span><h3>${safe(c.name)}</h3></div><div><button id="wb-rename">Adını değiştir</button><button id="wb-delete-folder">Sil</button></div></header>${wbPicker('wb-folder-picker',{s:1,a:1},'Ayet ekle')}<div class="wb-folder-verses">${c.refs.map((key,i)=>{const[s,a]=key.split(':').map(Number);return `<article><div class="wb-folder-ref"><strong>${names[s-1]} · ${a}. ayet</strong><div><button data-folder-up="${i}" ${i===0?'disabled':''} aria-label="Ayeti yukarı taşı">↑</button><button data-folder-down="${i}" ${i===c.refs.length-1?'disabled':''} aria-label="Ayeti aşağı taşı">↓</button><button data-folder-remove="${key}" aria-label="Koleksiyondan çıkar">${icon('close')}</button></div></div><p>${safe(translations[s-1].ayahs[a-1].text)}</p><footer><button data-wb-context="${key}">Sure içinde oku</button><button data-wb-tools="${key}">Ayet araçları ${icon('arrow')}</button></footer></article>`}).join('')||'<p class="wb-fine">İlk ayeti yukarıdan ekle. Okuma ekranındaki “Masa · Koleksiyon · Kart” düğmesiyle de ayet ekleyebilirsin.</p>'}</div>`:'<div class="wb-empty"><h3>Bir isimle başlar.</h3><p>“Tekrar okuyacaklarım” veya “Üzerinde düşündüklerim”… İlk koleksiyonunu oluştur.</p></div>'}</section></div>`;document.getElementById('wb-create-folder').onsubmit=e=>{e.preventDefault();const created=newCollection(document.getElementById('wb-folder-name').value);if(created){wbCollection=created.id;renderCollections()}};document.querySelectorAll('[data-folder]').forEach(b=>b.onclick=()=>{wbCollection=b.dataset.folder;renderCollections()});if(!c)return;bindWbPicker('wb-folder-picker',(s,a)=>{if(collectionAdd(c.id,s+':'+a))renderCollections()});document.getElementById('wb-rename').onclick=()=>{openModal('Koleksiyon adını değiştir',`<form id="wb-rename-form"><label for="wb-new-name">Koleksiyon adı</label><input id="wb-new-name" maxlength="60" required value="${safe(c.name)}"><button class="solid-button">Kaydet</button></form>`);document.getElementById('wb-rename-form').onsubmit=e=>{e.preventDefault();const name=document.getElementById('wb-new-name').value.trim();if(name){c.name=name;persistCollections();closeModal();renderCollections()}}};document.getElementById('wb-delete-folder').onclick=()=>{openModal('Koleksiyonu sil?',`<p>“${safe(c.name)}” koleksiyonu silinecek. Ayetlerin asıl metni, yer imlerin ve kişisel notların silinmez.</p><button id="wb-confirm-delete" class="solid-button">Bu koleksiyonu sil</button>`);document.getElementById('wb-confirm-delete').onclick=()=>{verseCollections=verseCollections.filter(x=>x.id!==c.id);persistCollections();closeModal();renderCollections()}};const move=(i,delta)=>{const n=i+delta;if(n<0||n>=c.refs.length)return;[c.refs[i],c.refs[n]]=[c.refs[n],c.refs[i]];persistCollections();renderCollections()};document.querySelectorAll('[data-folder-up]').forEach(b=>b.onclick=()=>move(+b.dataset.folderUp,-1));document.querySelectorAll('[data-folder-down]').forEach(b=>b.onclick=()=>move(+b.dataset.folderDown,1));document.querySelectorAll('[data-folder-remove]').forEach(b=>b.onclick=()=>{c.refs=c.refs.filter(k=>k!==b.dataset.folderRemove);persistCollections();renderCollections()});bindWorkbenchLinks()}
function renderCardStudio(){document.getElementById('wb-body').innerHTML=`<div class="wb-section-heading"><div><h2>Anlamı yanında taşı.</h2><p>Kaynak metin ve ayet referansıyla paylaşılabilir bir kart. Ayet metni düzenlenmez veya kısaltılmaz.</p></div></div><div class="wb-card-layout"><section class="wb-card-controls">${wbPicker('wb-card-picker',cardRef,'Ayeti seç')}<label>Tasarım<select id="wb-card-theme"><option value="sage">Adaçayı · sıcak ve sade</option><option value="night">Gece · derin yeşil</option><option value="paper">Kâğıt · klasik</option></select></label><label>Biçim<select id="wb-card-format"><option value="square">Kare · 1080 × 1080</option><option value="story">Hikâye · 1080 × 1920</option></select></label><label>Metin<select id="wb-card-language"><option value="both">Arapça + Türkçe meal</option><option value="tr">Yalnızca Türkçe meal</option><option value="ar">Yalnızca Arapça</option></select></label><p class="wb-fine">Uzun ayetlerde metnin tamamını korumak için kart aşağıya doğru uzatılır. Hiçbir ayet kesilmez. Görsel kaynak bir tefsir değildir.</p><button id="wb-card-download" class="solid-button" disabled>${icon('share')} PNG olarak indir</button><span id="wb-card-status" role="status">Yazı tipleri hazırlanıyor…</span></section><section class="wb-card-preview"><canvas id="wb-card-canvas" width="1080" height="1080" aria-label="Seçili ayetin paylaşım kartı"></canvas><details><summary>Görseldeki kaynak metin</summary><p id="wb-card-ar-source" lang="ar" dir="rtl"></p><p id="wb-card-tr-source"></p></details></section></div>`;bindWbPicker('wb-card-picker',(s,a)=>{cardRef={s,a};history.replaceState(null,'',`#atolye/kart/${s}/${a}`);renderCardPreview()});for(const name of ['theme','format','language']){const el=document.getElementById('wb-card-'+name);el.value=cardPrefs[name];el.onchange=()=>{cardPrefs[name]=el.value;renderCardPreview()}}document.getElementById('wb-card-download').onclick=()=>{const canvas=document.getElementById('wb-card-canvas'),fileName=`nur-${cardRef.s}-${cardRef.a}-${cardPrefs.theme}.png`;canvas.toBlob(blob=>{if(!blob){toast('Görsel oluşturulamadı.');return}const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=fileName;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500)},'image/png')};renderCardPreview()}
function canvasLines(ctx,text,width){const words=text.split(/\s+/),lines=[];let line='';for(const word of words){const candidate=line?line+' '+word:word;if(line&&ctx.measureText(candidate).width>width){lines.push(line);line=word}else line=candidate}if(line)lines.push(line);return lines}
async function renderCardPreview(){const generation=++cardGeneration,ref={...cardRef},prefs={...cardPrefs},canvas=document.getElementById('wb-card-canvas'),download=document.getElementById('wb-card-download'),status=document.getElementById('wb-card-status');if(!canvas)return;download.disabled=true;status.textContent='Kart hazırlanıyor…';const ar=surahs[ref.s-1].ayahs[ref.a-1].text,tr=translations[ref.s-1].ayahs[ref.a-1].text;document.getElementById('wb-card-ar-source').textContent=ar;document.getElementById('wb-card-tr-source').textContent=tr;try{await Promise.all([document.fonts.load('64px Amiri',ar),document.fonts.load('42px Manrope',tr)]);await document.fonts.ready;if(generation!==cardGeneration||!canvas.isConnected)return;const ctx=canvas.getContext('2d'),hasAr=prefs.language!=='tr',hasTr=prefs.language!=='ar';ctx.font='64px Amiri';const arLines=hasAr?canvasLines(ctx,ar,850):[];ctx.font='42px Manrope';const trLines=hasTr?canvasLines(ctx,tr,850):[];const content=arLines.length*104+trLines.length*70+(hasAr&&hasTr?80:0),base=prefs.format==='story'?1920:1080,height=Math.max(base,content+470);if(height>12000)throw Error('size');canvas.width=1080;canvas.height=height;const colors={sage:{bg:'#eef2e6',ink:'#35573e',muted:'#7c8f6d',line:'#c8d3ba'},night:{bg:'#102c24',ink:'#e0e6ca',muted:'#a2b28f',line:'#466047'},paper:{bg:'#faf5e9',ink:'#5d503b',muted:'#9c8967',line:'#ded1b7'}}[prefs.theme];ctx.fillStyle=colors.bg;ctx.fillRect(0,0,1080,height);ctx.strokeStyle=colors.line;ctx.lineWidth=2;ctx.strokeRect(38,38,1004,height-76);ctx.beginPath();ctx.arc(540,155,68,Math.PI,0);ctx.stroke();ctx.textAlign='center';ctx.direction='ltr';ctx.fillStyle=colors.muted;ctx.font='21px Manrope';ctx.fillText('N Û R  /  A Y E T  K A R T I',540,205);let y=270+Math.max(0,(height-content-470)/2);if(hasAr){ctx.font='64px Amiri';ctx.fillStyle=colors.ink;ctx.direction='rtl';ctx.textAlign='right';ctx.textBaseline='alphabetic';for(const line of arLines){ctx.fillText(line,965,y+72);y+=104}if(hasTr){y+=37;ctx.strokeStyle=colors.line;ctx.beginPath();ctx.moveTo(390,y);ctx.lineTo(690,y);ctx.stroke();y+=43}}if(hasTr){ctx.direction='ltr';ctx.textAlign='left';ctx.fillStyle=colors.ink;ctx.font='42px Manrope';for(const line of trLines){ctx.fillText(line,115,y+48);y+=70}}ctx.direction='ltr';ctx.textAlign='center';ctx.fillStyle=colors.muted;ctx.font='27px Manrope';ctx.fillText(`${names[ref.s-1]} Suresi · ${ref.a}. ayet`,540,height-133);ctx.font='19px Manrope';ctx.fillText(hasTr?'Diyanet Meali · '+ref.s+':'+ref.a:'Arapça: Osmanî metin · '+ref.s+':'+ref.a,540,height-91);ctx.font='16px Manrope';ctx.fillText('Nûr · Kur’an-ı Kerim',540,height-63);status.textContent=`Hazır · 1080 × ${height} px${height>base?' · Metnin tamamı için uzatıldı':''}`;download.disabled=false}catch{if(generation===cardGeneration&&canvas.isConnected){status.textContent='Kart hazırlanamadı. Yazı tiplerini yüklemek için bağlantını kontrol et veya başka bir ayet seç.';download.disabled=true}}}

let numberBook=null,numberRequest=0,numberFilter='all',numberQuery='',numberPage=0;
const numberTopics={method:'Yöntem ve giriş',adam:'Âdem',noah:'Nuh ve tufan',hud:'Hûd ve Âd',context:'İrem ve Punt'};
function initNumberBookMenu(){const b=document.createElement('button');b.className='nav-item';b.dataset.nav='numbers';b.innerHTML=icon('book')+' Sayısal İncelemeler';b.onclick=()=>openNumberBook();document.querySelector('.sidebar nav').append(b)}
function addNumberBookEntry(after){const b=document.createElement('button');b.className='number-book-entry';b.innerHTML=`${icon('book')}<span><small>KİTAPTAN TÜRKÇE İNCELEMELER · İLK BÖLÜM HAZIR</small><strong>Bir sayının arkasındaki hesabı aç.</strong><em>İddia, kaynak sayfası, işlem ve açık sayım kuralları.</em></span>${icon('arrow')}`;b.onclick=()=>openNumberBook();after.after(b)}
function numberEquation(step){return step.operands.join(step.operator==='add'?' + ':' − ')}
function numberResult(step,values=step.operands){return step.operator==='add'?values.reduce((n,v)=>n+v,0):values[0]-values.slice(1).reduce((n,v)=>n+v,0)}
function numberSource(item){return 'PDF s. '+item.pages.join(', ')}
function numberClean(text,mergeAlif=false){let clean=text.normalize('NFC').replace(/[\u06D6-\u06ED\u08D3-\u08FF\u0640]/gu,'');if(mergeAlif)clean=clean.replace(/[أإآٱ]/gu,'ا');return [...clean].filter(c=>/\p{L}/u.test(c)&&/\p{Script=Arabic}/u.test(c)).join('')}
function numberMeasure(spec,options={exclude:true,merge:false}){const q=surahs[spec.surah-1],start=spec.start||1,end=spec.end||q.ayahs.length,rows=q.ayahs.slice(start-1,end);if(spec.kind==='verses')return rows.length;const basmala=surahs[0].ayahs[0].text.trim();let texts=rows.map(a=>{let t=a.text.trim();if(options.exclude&&spec.surah!==1&&a.numberInSurah===1&&t.startsWith(basmala))t=t.slice(basmala.length).trim();return t});if(spec.kind==='words')return texts.reduce((n,t)=>n+t.split(/\s+/u).filter(word=>numberClean(word).length>0).length,0);const letters=numberClean(texts.join(' '),options.merge);return spec.kind==='letters'?[...letters].length:[...letters].filter(c=>(spec.letters||[]).includes(c)).length}
async function openNumberBook(id=''){const fromRoute=routeSync,request=++numberRequest;page='numbers';closeModal();observer?.disconnect();focusMode=false;document.body.classList.remove('focus-mode');document.querySelectorAll('[data-nav]').forEach(b=>b.classList.toggle('active',b.dataset.nav==='numbers'||(b.dataset.nav==='explore'&&!!b.closest('.mobile-navigation'))));document.getElementById('crumb').textContent='Sayısal İncelemeler';if(!fromRoute)history.pushState(null,'',id?'#sayisal/'+id:'#sayisal');document.getElementById('content').innerHTML='<div class="empty" role="status">Kaynaklı incelemeler hazırlanıyor…</div>';try{if(!numberBook){const r=await fetch('/data/qurancode-tr.json');if(!r.ok)throw Error('data');const d=await r.json();if(d.version!==1||!Array.isArray(d.items))throw Error('format');numberBook=d}if(request!==numberRequest||page!=='numbers')return;const item=numberBook.items.find(x=>x.id===id);if(item)renderNumberDetail(item);else renderNumberLibrary();window.scrollTo(0,0)}catch{if(page==='numbers'&&request===numberRequest){document.getElementById('content').innerHTML='<div class="empty">İnceleme verileri yüklenemedi. Çevrimdışıyken önce bu sürümün içeriklerini hazırlamış olmalısın.<br><button id="number-retry">Tekrar dene</button></div>';document.getElementById('number-retry').onclick=()=>openNumberBook(id)}}}
function renderNumberLibrary(){const data=numberBook,operations=data.items.reduce((n,x)=>n+x.steps.length,0);document.getElementById('content').innerHTML=`<div class="number-book-page fade-in"><header class="number-book-hero"><div><span class="mini-label">BİR İDDİAYI SONUCUNDAN ÖNCE, YÖNTEMİYLE TANI</span><h1>Sayılar ne söylüyor?<br><em>Hesabı birlikte açalım.</em></h1><p>Hişam Emin el-Mısrî’nin <i>Historical Quran Code</i> kitabındaki sayısal savların Türkçe incelemesi. PDF görüntüleyici değil; kaynaklı anlatımlar, tablolar ve hesap araçları.</p></div><div class="number-book-seal"><span>İNCELENEN İLK DİLİM</span><strong>08—30</strong><small>248 sayfalık kitabın tamamı<br>henüz Türkçeleştirilmedi.</small></div></header><div class="number-progress"><strong>Giriş ve I. bölüm hazır.</strong><span>${data.items.length} Türkçe kayıt · ${operations} işlem · 2 kaynak tablo. II–V. bölümler, sonuç ve ekler bekliyor.</span></div><section class="number-principles"><article><span>01</span><h2>Yazarın savı</h2><p>Sayılardan tarih çıkarımları yazara atfedilir; yerleşik tarih bilgisi olarak sunulmaz.</p></article><article><span>02</span><h2>Aritmetik kontrol</h2><p>Toplam ve fark yeniden hesaplanabilir. İşlemin doğru olması, tarih yorumunu kanıtlamaz.</p></article><article><span>03</span><h2>Açık sayım kuralı</h2><p>Yerel Kur’an metnini belirtilen kuralla say. Yazım veya sayım farkları gizlenmez.</p></article></section><section class="number-library"><div class="number-filter"><label>${icon('search')}<input id="number-search" type="search" placeholder="Konu, sayı veya iddia ara…" aria-label="İncelemelerde ara" value="${safe(numberQuery)}"></label><select id="number-topic" aria-label="Konu seç"><option value="all">Bütün konular</option>${Object.entries(numberTopics).map(([k,v])=>`<option value="${k}" ${numberFilter===k?'selected':''}>${v}</option>`).join('')}</select><span id="number-results" role="status"></span></div><div id="number-claim-list" class="number-claim-list"></div><div class="number-pagination"><button id="number-prev">← Önceki</button><span id="number-page-label"></span><button id="number-next">Sonraki →</button></div></section><details class="number-contents"><summary>Kitabın tamamı için kapsam ve hazırlık durumu</summary><p>Kaynak dosya 248 sayfadır. Aşağıdaki bekleyen bölümlere ait bütün savların hazır olduğu iddia edilmez.</p>${data.chapters.map(ch=>`<div><strong>${safe(ch.title)}</strong><span>PDF ${ch.range.join('–')}</span><b class="${ch.ready?'ready':''}">${ch.ready?'Hazır':'Türkçe inceleme bekliyor'}</b></div>`).join('')}</details><details class="number-timeline"><summary>I. bölümün yazar tarafından önerilen kronolojisi</summary><p>Bu tarihler yazarın modeline aittir; bağımsız olarak doğrulanmış tarihler olarak gösterilmez.</p>${data.timeline.map(([title,year])=>`<div><span>${safe(title)}</span><strong>MÖ ${year}</strong></div>`).join('')}</details><footer class="number-book-source">Kaynak: ${safe(data.author)}, ${safe(data.title)} (${data.year}). ISBN ${safe(data.isbn)}. Sayfa numaraları yüklenen PDF’nin sırasını gösterir. Türkçe metinler sayısal savları açıklayan uyarlamalardır; kitabın kelimesi kelimesine çevirisi değildir.</footer></div>`;document.getElementById('number-search').oninput=e=>{numberQuery=e.target.value;numberPage=0;updateNumberCards()};document.getElementById('number-topic').onchange=e=>{numberFilter=e.target.value;numberPage=0;updateNumberCards()};document.getElementById('number-prev').onclick=()=>{numberPage--;updateNumberCards();document.querySelector('.number-filter').scrollIntoView({block:'start'})};document.getElementById('number-next').onclick=()=>{numberPage++;updateNumberCards();document.querySelector('.number-filter').scrollIntoView({block:'start'})};updateNumberCards()}
function updateNumberCards(){const q=foldSearch(numberQuery),items=numberBook.items.filter(x=>(numberFilter==='all'||x.topic===numberFilter)&&(!q||foldSearch(x.title+' '+x.summary+' '+x.steps.map(s=>numberEquation(s)+' '+s.expected).join(' ')+' '+x.counts.map(c=>c.claimed).join(' ')+' '+(x.table?x.table.rows.flat().join(' '):'')+' '+x.notes.join(' ')).includes(q)));const pages=Math.max(1,Math.ceil(items.length/8));numberPage=Math.max(0,Math.min(numberPage,pages-1));document.getElementById('number-prev').disabled=numberPage===0;document.getElementById('number-next').disabled=numberPage===pages-1;document.getElementById('number-page-label').textContent=(numberPage+1)+' / '+pages;document.getElementById('number-results').textContent=items.length+' kayıt';document.getElementById('number-claim-list').innerHTML=items.slice(numberPage*8,numberPage*8+8).map(x=>`<button class="number-claim" data-number-id="${x.id}"><span>${safe(numberTopics[x.topic])}<small>${numberSource(x)}</small></span><h2>${safe(x.title)}</h2><p>${safe(x.summary)}</p><footer><span>${x.table?'Kaynak tablo':x.steps.length?x.steps.length+' işlem':x.counts.length?'Sayım iddiası':'Yöntem / bağlam'}</span>İncele ${icon('arrow')}</footer></button>`).join('')||'<div class="wb-empty">Bu aramada eşleşen kayıt yok. Başka bir sayı veya konu dene.</div>';document.querySelectorAll('[data-number-id]').forEach(b=>b.onclick=()=>openNumberBook(b.dataset.numberId))}
function renderNumberDetail(item){const eqs=item.steps,table=item.table;document.getElementById('content').innerHTML=`<div class="number-detail fade-in"><button id="number-back">${icon('back')} Bütün incelemeler</button><header><span class="mini-label">${safe(numberTopics[item.topic])} · ${numberSource(item)}</span><h1>${safe(item.title)}</h1><p>Kitabın sayısal savı · Türkçe açıklama</p></header><div class="number-detail-layout"><section><article class="number-author-claim"><span class="mini-label">YAZARIN İLERİ SÜRDÜĞÜ</span><p>${safe(item.summary)}</p></article>${eqs.length?`<section class="number-equations"><h2>İşlemi adım adım gör</h2>${eqs.map((s,i)=>`<article><small>${safe(s.label)}</small><div class="number-equation" dir="ltr">${numberEquation(s)} <b>= ${s.expected}</b></div><span class="number-check">${numberResult(s)===s.expected?'✓ Aritmetik eşitlik doğru':'İşlem ile basılı sonuç farklı'} · ${safe(s.unit)}</span><button data-number-equation="${i}">Girdileri değiştirip hesapla ${icon('arrow')}</button></article>`).join('')}<p class="number-fine">Bu etiket yalnızca belirtilen sayılarla yapılan işlemi denetler. Tarih, yaş veya dinî çıkarımın kanıtlandığı anlamına gelmez.</p></section>`:''}${table?`<section class="number-source-table"><h2>${safe(table.title)}</h2><p>Kitaptaki ayet ve harf değerleri aşağıya aktarılmıştır. Sütun kaynağın iddiasını gösterir; yerel sayım sonucu değildir.</p><div class="number-table-scroll"><table><thead><tr><th>Ayet</th><th>Kitaptaki harf sayısı</th></tr></thead><tbody>${table.rows.map(([s,a,n])=>`<tr><td><button data-number-ref="${s}:${a}">${names[s-1]} ${s}:${a}</button></td><td>${n}</td></tr>`).join('')}</tbody><tfoot><tr><th>Hesaplanan toplam</th><td>${table.rows.reduce((n,r)=>n+r[2],0)}</td></tr><tr><th>Kitabın toplamı</th><td>${table.claimedTotal}</td></tr></tfoot></table></div></section>`:''}${item.refs.length?`<div class="number-refs"><span>İlgili ayetleri tam sure içinde aç</span>${item.refs.map(([s,a])=>`<button data-number-ref="${s}:${a}">${names[s-1]} · ${a} ${icon('arrow')}</button>`).join('')}</div>`:''}${item.counts.length?`<section class="number-count-lab"><span class="mini-label">YEREL METİN ÜZERİNDE DENE</span><h2>Sayım kuralını görünür kıl.</h2><p>Bu laboratuvar sitenin Osmanî metnini sayar. Kitabın kullandığı baskı ve bütün sayım ayrıntıları aynı kabul edilmez.</p><label>Kitaptaki sayım<select id="number-count-spec">${item.counts.map((s,i)=>`<option value="${i}">${names[s.surah-1]} ${s.start?s.start+'–'+s.end+' · ':''}${safe(s.label||({words:'Kelime',letters:'Harf',verses:'Ayet',occurrences:'Harf tekrarı'})[s.kind])} · kitap: ${s.claimed}</option>`).join('')}</select></label><label class="number-count-toggle"><input id="number-no-basmala" type="checkbox" checked> Fâtiha dışında sure başındaki besmeleyi çıkar</label><label class="number-count-toggle"><input id="number-merge-alif" type="checkbox"> Elif biçimlerini birleştir: ا أ إ آ ٱ</label><div id="number-count-output" role="status"></div><details class="number-count-rules"><summary>Kullanılan kuralın tam açıklaması</summary><p>Kelime: boşlukla ayrılan, en az bir Arapça harf taşıyan birim. Bağımsız durak işaretleri kelime değildir. Harf: NFC Unicode normalleştirmesinden sonra Arapça harf karakterleri. Hareke, uzatma çizgisi ve U+06D6–06ED / U+08D3–08FF Kur’an işaretleri çıkarılır. Küçük üst elif ek bir harf sayılmaz. Harf tekrarında yalnızca belirtilen harfler sayılır; elif birleştirme seçeneği açıksa أ إ آ ٱ biçimleri ا olur. Yâ/elif-i maksûre ve hâ/tâ-i merbûta kendiliğinden birleştirilmez. Baş/son boşluklar ve BOM temizlendikten sonra besmele yalnızca metnin ilk ayetinin başında tam eşleşiyorsa çıkarılır; Fâtiha’nın birinci ayeti korunur. Ayet sayısında bu seçenekler sonucu değiştirmez.</p></details></section>`:''}</section><aside class="number-method-note"><span class="mini-label">SONUÇTAN ÖNCE DAYANAKLAR</span><h2>Neyi doğruladık?</h2><p>Burada matematiksel işlem ile sayının nereden geldiği ve ona verilen anlam birbirinden ayrılır.</p><ol><li><strong>İşlem:</strong> verilen rakamlarla toplam veya fark.</li><li><strong>Sayım:</strong> metin sürümü, kapsam ve harf/kelime kuralı.</li><li><strong>Yorum:</strong> sayıyı belirli bir kişi, yaş veya takvim yılına eşleme.</li></ol>${item.notes.length?`<h3>Bu kayda özgü notlar</h3><ul>${item.notes.map(n=>`<li>${safe(n)}</li>`).join('')}</ul>`:''}<p class="number-fine">Yazar girişte bütün sonuçların yüzde yüz doğru olduğunu ileri sürmediğini belirtir (PDF 10). Bu içerik, onun savlarının incelenebilir aktarımıdır.</p><footer>${safe(numberBook.author)}<br><i>${safe(numberBook.title)}</i><br>${numberSource(item)}</footer></aside></div></div>`;document.getElementById('number-back').onclick=()=>openNumberBook();document.querySelectorAll('[data-number-ref]').forEach(b=>b.onclick=()=>openSurah(...b.dataset.numberRef.split(':').map(Number)));document.querySelectorAll('[data-number-equation]').forEach(b=>b.onclick=()=>showNumberCalculator(eqs[+b.dataset.numberEquation]));if(item.counts.length){const update=()=>{const spec=item.counts[+document.getElementById('number-count-spec').value],current=numberMeasure(spec,{exclude:document.getElementById('number-no-basmala').checked,merge:document.getElementById('number-merge-alif').checked});document.getElementById('number-count-output').innerHTML=`<div><span>Kitabın sayısı</span><strong>${spec.claimed}</strong></div><div><span>Bu kuralla yerel sayım</span><strong>${current}</strong></div><p>${current===spec.claimed?'Bu kuralla sayılar eşleşti. Bu eşleşme tarihsel yorumu tek başına doğrulamaz.':'Bu kuralla sayılar farklı. Fark: '+(current-spec.claimed)+'. Bu, tek başına kitabın yanlışlığını veya doğruluğunu kanıtlamaz; metin ve sayım ölçütleri karşılaştırılmalıdır.'}</p>`};['number-count-spec','number-no-basmala','number-merge-alif'].forEach(id=>document.getElementById(id).onchange=update);update()}}
function showNumberCalculator(step){openModal('Aynı işlemi yeniden hesapla',`<p>Kaynak işlem: <b dir="ltr">${numberEquation(step)} = ${step.expected}</b>. Aşağıdaki girdileri değiştirmek, kitabın savını değiştirmez.</p><form id="number-calculator"><div class="number-calc-inputs">${step.operands.map((n,i)=>`<label>${i+1}. sayı<input type="number" name="n${i}" min="0" max="1000000" step="1" required value="${n}"></label>`).join('')}</div><button class="solid-button" type="submit">Hesapla</button><output id="number-calculator-result" aria-live="polite">Sonuç: ${numberResult(step)} ${safe(step.unit)}</output></form>`);document.getElementById('number-calculator').onsubmit=e=>{e.preventDefault();const values=step.operands.map((_,i)=>+e.target.elements['n'+i].value);if(values.some(n=>!Number.isInteger(n)||n<0||n>1000000))return;document.getElementById('number-calculator-result').textContent='Bu girdilerle sonuç: '+numberResult(step,values)+' '+step.unit}}

matchMedia('(prefers-reduced-motion:reduce)').addEventListener('change',syncCosmosMotion);
matchMedia('(max-width:600px)').addEventListener('change',()=>{if(page==='atlas')updateAtlas()});
shell();if('serviceWorker' in navigator)navigator.serviceWorker.getRegistration().then(reg=>reg?.update()).catch(()=>{});const mobileSearch=matchMedia('(max-width:780px)');const updateSearchHint=()=>{document.getElementById('search').placeholder=mobileSearch.matches?'Kur’an’da ara…':'Sure, ayet veya bir kelime ara…'};mobileSearch.addEventListener('change',updateSearchHint);updateSearchHint();document.getElementById('content').innerHTML='<div class="empty">۞<br>Huzura açılan sayfalar hazırlanıyor…</div>';
try{const [ar,tr]=await Promise.all([fetch('/data/arabic.json').then(r=>r.json()),fetch('/data/turkish.json').then(r=>r.json())]);surahs=ar.surahs;translations=tr.surahs;if(surahs.length!==114||surahs.reduce((n,s)=>n+s.ayahs.length,0)!==6236)throw Error('Metin bütünlüğü doğrulanamadı');initAppFeatures();routeFromUrl()}catch(e){document.getElementById('content').innerHTML='<div class="empty">Kur’an metni yüklenemedi. Lütfen sayfayı yenile.<br><button onclick="location.reload()">Tekrar dene</button></div>';console.error(e)}
